+//! openab-cp — OpenAB Agent Control Plane.
+//!
+//! Hub-and-spoke registration and routing for direct agent-to-agent
+//! delegation, per `docs/adr/agent-control-plane.md`. Runtimes dial out and
+//! register over WebSocket; the CP authenticates them against config-bound
+//! identities, enforces delegation policy authoritatively, and routes
+//! `cp/delegate` / `cp/delegate_result` frames between them.
+
+pub mod config;
+pub mod policy;
+pub mod proto;
+pub mod registry;
+pub mod router;
+pub mod server;

@@ -0,0 +1,56 @@
+//! Standalone control-plane binary.
+
+use std::sync::Arc;
+
+use anyhow::{Context, Result};
+use clap::Parser;
+use tracing::info;
+
+use openab_cp::config::CpConfig;
+use openab_cp::server::{app, run_sweeper, AppState};
+
+#[derive(Parser)]
+#[command(name = "openab-cp", about = "OpenAB Agent Control Plane")]
+struct Cli {
+    /// Path to the CP config file (TOML).
+    #[arg(short, long, default_value = "cp.toml")]
+    config: String,
+}
+
+#[tokio::main]
+async fn main() -> Result<()> {
